    const hasLine = (x, row) => { let n = 0; for (let y = row.a; y <= row.b; y++) { let hit = false; for (let dx = -2; dx <= 2; dx++) if (dark(gray[y * W + x + dx])) hit = true; if (hit) n++; } return n >= (row.b - row.a + 1) * 0.85; };
