    let pre = m[1]; const f = {};
    if (m[2] === 'クリーチャー') f.type = 'クリーチャー'; else if (m[2] === '呪文') f.type = '呪文';
    const rm = pre.match(/^(?:.*?の)?([^\sの・]+(?:・[^\sの・]+)*)・$/);
