      if (ev === 'etb' && x.how !== 'summon' && /召喚によって(バトルゾーンに)?出た時/.test(s.text) && !TRIG.etb.test(s.text.replace(/召喚によって(バトルゾーンに)?出た時/g, ''))) return;
      await claudeResolve(uid, ev, s, { how: x.how, sideIdx: si });
